import{_ as o,o as t,c as r,a5 as s}from"./chunks/framework.BfQ7H7Qx.js";const g=JSON.parse('{"title":"FR 3.6.25 — Create Survey","description":"","frontmatter":{},"headers":[],"relativePath":"feature/srs/05-content-task-workflow/3-6-25-create-survey/spec.md","filePath":"feature/srs/05-content-task-workflow/3-6-25-create-survey/spec.md"}'),c={name:"feature/srs/05-content-task-workflow/3-6-25-create-survey/spec.md"};function a(n,e,i,d,l,u){return t(),r("div",null,[...e[0]||(e[0]=[s('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Domain Index</a> · <strong>Spec</strong> · <a href="./plan.html">Plan</a> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="fr-3-6-25-—-create-survey" tabindex="-1">FR 3.6.25 — Create Survey <a class="header-anchor" href="#fr-3-6-25-—-create-survey" aria-label="Permalink to &quot;FR 3.6.25 — Create Survey&quot;">​</a></h1><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>FR Code</strong></td><td style="text-align:left;"><code>3.6.25</code></td></tr><tr><td style="text-align:left;"><strong>Use Case ID</strong></td><td style="text-align:left;"><code>UC-077</code></td></tr><tr><td style="text-align:left;"><strong>Feature</strong></td><td style="text-align:left;">Create Survey</td></tr><tr><td style="text-align:left;"><strong>Domain</strong></td><td style="text-align:left;">Content &amp; Workflow (<code>FR 3.6</code>)</td></tr><tr><td style="text-align:left;"><strong>Canonical Actors / Roles</strong></td><td style="text-align:left;"><code>Owner, Manager, Creator</code></td></tr><tr><td style="text-align:left;"><strong>Business Rules</strong></td><td style="text-align:left;"><code>BR-40</code></td></tr><tr><td style="text-align:left;"><strong>Document Status</strong></td><td style="text-align:left;">Implemented &amp; Verified</td></tr></tbody></table><h2 id="_1-objective-functional-scope" tabindex="-1">1. Objective &amp; Functional Scope <a class="header-anchor" href="#_1-objective-functional-scope" aria-label="Permalink to &quot;1. Objective &amp; Functional Scope&quot;">​</a></h2><p>Tạo biểu mẫu khảo sát tương tác phục vụ sự kiện, workshop hoặc thu thập ý kiến khách hàng trong chiến dịch (Create Survey — /workspaces/:id/surveys/new). Hỗ trợ thiết kế tiêu đề khảo sát, mô tả, thời hạn đóng biểu mẫu và danh sách câu hỏi đa dạng (Trắc nghiệm 1 lựa chọn, Nhiều lựa chọn, Thang điểm đánh giá, Câu trả lời văn bản tự do) kèm đường dẫn công khai để chia sẻ (BR-40).</p><p><strong>Consolidated Implementation Scope:</strong> Implemented end-to-end in <code>SurveyServiceImpl</code> (<code>BR-40</code>): <code>Owner, Manager, Creator</code> builds and publishes multi-question forms (<code>TEXT</code>, <code>SINGLE_CHOICE</code>, <code>MULTIPLE_CHOICE</code>, <code>RATING</code> 1–5, file/attachment answers) on <code>SURVEY</code> or <code>WORKSHOP</code> tasks (enforcing <code>SectionPolicy</code> on <code>SURVEY.FORM</code> / <code>WORKSHOP.REGISTRATION</code>), automatically provisions a linked Google Spreadsheet via <code>GoogleSheetsService</code>, generates a public shareable link (<code>/public/surveys/{token}</code>), and appends public <code>Guest</code> submissions to both MongoDB <code>survey_responses</code> and Google Sheets.</p><h2 id="_2-user-story" tabindex="-1">2. User Story <a class="header-anchor" href="#_2-user-story" aria-label="Permalink to &quot;2. User Story&quot;">​</a></h2><p>As an authorized actor (<code>Owner, Manager, Creator</code>), I want to execute <strong>Create Survey</strong> within my active Workspace with strict role/audience isolation, version/concurrency safety, and responsive feedback, so that content production workflows satisfy <code>BR-40</code> across Web and Mobile.</p><h2 id="_3-acceptance-criteria" tabindex="-1">3. Acceptance Criteria <a class="header-anchor" href="#_3-acceptance-criteria" aria-label="Permalink to &quot;3. Acceptance Criteria&quot;">​</a></h2><ol><li><strong>Workspace &amp; Role Authorization:</strong> Only authenticated actors holding <code>Owner, Manager, Creator</code> in the target Workspace (plus <code>Guest</code> solely on public survey token endpoints in <code>3.6.25</code>) may invoke <code>POST /api/v1/workspaces/{workspaceId}/tasks/{taskId}/survey · GET /api/v1/workspaces/{workspaceId}/tasks/{taskId}/survey · GET /api/v1/public/surveys/{token} · POST /api/v1/public/surveys/{token}/submit</code>; revoked or cross-workspace callers are rejected (<code>401</code> / <code>403</code>).</li><li><strong>Core Domain &amp; Security Invariants (<code>BR-40</code>):</strong> <code>SurveyServiceImpl, GoogleSheetsService, SectionService (</code>SURVEY.FORM<code>/</code>WORKSHOP.REGISTRATION<code>)</code> enforces all state-machine locks, audience visibility filters (<code>INTERNAL</code> vs per-<code>clientProfileId</code> <code>CLIENT</code>), storage/file validation rules, and Workspace timezone boundaries (<code>Asia/Ho_Chi_Minh</code> default).</li><li><strong>Persistence &amp; Envelope Contract:</strong> Operations on MongoDB <code>surveys</code> (<code>SurveyDocument</code>: <code>taskId</code>, <code>workspaceId</code>, <code>publicToken</code>, <code>questions</code>, <code>spreadsheetId</code>, <code>spreadsheetUrl</code>, <code>published</code>), <code>survey_responses</code> (<code>SurveyResponseDocument</code>) return standardized <code>ApiResponse&lt;T&gt;</code> payloads (or authenticated binary/WebSocket frames where applicable) with deterministic <code>ErrorCode</code> mappings (<code>400 VALIDATION_ERROR</code> (answer length / rating bounds <code>1..5</code>), <code>403 FORBIDDEN</code> (section editor policy), <code>404 SURVEY_NOT_FOUND</code> / <code>TASK_NOT_FOUND</code> (<code>BR-40</code>)).</li><li><strong>Internationalization (<code>vi</code> / <code>en</code>):</strong> Every label, badge, filter pill, modal prompt, empty state, and error toast uses parallel translation keys (<code>survey.editor.* / survey.public.*</code>) in <code>src/i18n/locales/vi/*.json</code> and <code>en/*.json</code> — zero hardcoded UI text.</li><li><strong>Semantic Light/Dark Theme &amp; Accessibility:</strong> Web (<code>src/pages/tasks/survey-editor/index.tsx</code>, <code>src/pages/public-survey/index.tsx</code>, <code>src/pages/public-survey/components/{PublicSurveyHeader,PublicQuestionCard,PublicSurveySuccess}.tsx</code>, <code>src/services/surveyService.ts</code>) and Mobile (<code>src/screens/content/TaskSurveySummaryScreen.tsx</code>, <code>src/services/taskService.ts</code>) components use semantic CSS variables / <code>dark:</code> Tailwind tokens and <code>useTheme()</code> tokens, supporting keyboard navigation (<code>Enter</code>/<code>Escape</code>/focus return) and mobile viewports.</li></ol><h2 id="_4-ui-ux-screen-states" tabindex="-1">4. UI / UX &amp; Screen States <a class="header-anchor" href="#_4-ui-ux-screen-states" aria-label="Permalink to &quot;4. UI / UX &amp; Screen States&quot;">​</a></h2><ul><li><strong>Web Surface (<code>brandhub-web</code>):</strong> <code>src/pages/tasks/survey-editor/index.tsx</code>, <code>src/pages/public-survey/index.tsx</code>, <code>src/pages/public-survey/components/{PublicSurveyHeader,PublicQuestionCard,PublicSurveySuccess}.tsx</code>, <code>src/services/surveyService.ts</code></li><li><strong>Mobile Surface (<code>brandhub-mobile-app</code>):</strong> <code>src/screens/content/TaskSurveySummaryScreen.tsx</code>, <code>src/services/taskService.ts</code></li><li><strong>Required UI States:</strong><ul><li><strong>Loading / Pending:</strong> Skeleton placeholders, progress indicators for uploads/imports, and disabled duplicate-submit triggers.</li><li><strong>Empty State:</strong> Clear localized explanation with role-appropriate CTA — never substituting synthetic mock items.</li><li><strong>Conflict / Warning:</strong> Preserves unsaved user drafts on <code>409</code> conflicts and surfaces inline warnings (such as <code>RAW</code> unedited photo badges or compliance warnings).</li><li><strong>Error / Retry:</strong> Actionable inline/banner error state with retry capability.</li></ul></li></ul><h2 id="_5-api-realtime-contract" tabindex="-1">5. API &amp; Realtime Contract <a class="header-anchor" href="#_5-api-realtime-contract" aria-label="Permalink to &quot;5. API &amp; Realtime Contract&quot;">​</a></h2><ul><li><strong>Endpoints / Channels:</strong> <code>POST /api/v1/workspaces/{workspaceId}/tasks/{taskId}/survey · GET /api/v1/workspaces/{workspaceId}/tasks/{taskId}/survey · GET /api/v1/public/surveys/{token} · POST /api/v1/public/surveys/{token}/submit</code></li><li><strong>Controllers (<code>brandhub-business-service</code>):</strong> <code>SurveyController.saveOrPublishSurvey() / getSurveyByTask(), PublicSurveyController.getPublicSurvey() / submitSurvey()</code></li><li><strong>Services:</strong> <code>SurveyServiceImpl, GoogleSheetsService, SectionService (</code>SURVEY.FORM<code>/</code>WORKSHOP.REGISTRATION<code>)</code></li><li><strong>Repositories / Stores:</strong> SurveyMongoRepository, SurveyResponseMongoRepository, TaskMongoRepository</li></ul><h2 id="_6-error-handling-edge-cases" tabindex="-1">6. Error Handling &amp; Edge Cases <a class="header-anchor" href="#_6-error-handling-edge-cases" aria-label="Permalink to &quot;6. Error Handling &amp; Edge Cases&quot;">​</a></h2><ul><li><strong>Domain Error Codes:</strong> <code>400 VALIDATION_ERROR</code> (answer length / rating bounds <code>1..5</code>), <code>403 FORBIDDEN</code> (section editor policy), <code>404 SURVEY_NOT_FOUND</code> / <code>TASK_NOT_FOUND</code> (<code>BR-40</code>).</li><li><strong>Audience &amp; Removed-Member Isolation:</strong> Removed or deactivated Workspace members lose read/write/WebSocket access immediately on the next request or STOMP frame; <code>Client</code> actors never see <code>INTERNAL</code>-only materials or other <code>ClientProfile</code> assets.</li><li><strong>Idempotency &amp; Concurrency:</strong> Optimistic revision checks (<code>workflowRevision</code>, <code>revision</code>, <code>clientMessageId</code>, <code>DriveOperationLease</code>) prevent race-condition overwrites and duplicate records on retry.</li></ul><h2 id="_7-definition-of-done-cross-references" tabindex="-1">7. Definition of Done &amp; Cross-References <a class="header-anchor" href="#_7-definition-of-done-cross-references" aria-label="Permalink to &quot;7. Definition of Done &amp; Cross-References&quot;">​</a></h2><ul><li><strong>Definition of Done:</strong> Backend endpoints/handlers verified by automated tests (<a href="./test.html">test.md</a>), Web &amp; Mobile UI integrated against live APIs, <code>vi</code>/<code>en</code> locale parity verified, and Light/Dark themes verified.</li><li><strong>Out of Scope:</strong> Adjacent workflow capabilities covered by sibling FRs in <code>3.6.1–3.6.35</code> and social publishing execution in <code>3.8.1–3.8.15</code>.</li><li><strong>Related Documentation:</strong> <a href="./../../../../ba/05-content-task-workflow.html">BA Content &amp; Workflow Spec</a> · <a href="./../../../../ba/12-state-machines.html">State Machines</a> · <a href="./../../../../ba/README.html">BA Overview</a> · <a href="./../../../modules/README.html">Module Specs Index</a> · <a href="./test.html">Test Suite</a>.</li></ul>',18)])])}const h=o(c,[["render",a]]);export{g as __pageData,h as default};
